      "name": "Finset.gcd_ne_zero_iff",
      "type": " {α : Type u_2} {β : Type u_3} [CommMonoidWithZero α] [NormalizedGCDMonoid α] {s : Finset β} {f : β → α} : s.gcd f ≠ 0 ↔ ∃ x ∈ s, f x ≠ 0",
      "module": "Mathlib.Algebra.GCDMonoid.Finset"
    },
    {
      "name": "Finset.extract_gcd",
      "type": " {α : Type u_2} {β : Type u_3} [CommMonoidWithZero α] [NormalizedGCDMonoid α] {s : Finset β} (f : β → α) (hs : s.Nonempty) : ∃ g, (∀ b ∈ s, f b = s.gcd f * g b) ∧ s.gcd g = 1",
      "module": "Mathlib.Algebra.GCDMonoid.Finset"
    },
    {
      "name": "Finset.extract_gcd'",
      "type": " {α : Type u_2} {β : Type u_3} [CommMonoidWithZero α] [NormalizedGCDMonoid α] {s : Finset β} (f g : β → α) (hs : ∃ x ∈ s, f x ≠ 0) (hg : ∀ b ∈ s, f b = s.gcd f * g b) : s.gcd g = 1",
      "module": "Mathlib.Algebra.GCDMonoid.Finset"
    },
    {
      "name": "Finset.gcd_eq_sum_mul",
      "type": " {R : Type u} {α : Type u_1} [CommRing R] [IsBezout R] [NormalizedGCDMonoid R] (s : Finset α) (f : α → R) : ∃ g, s.gcd f = ∑ a ∈ s, f a * g a",
